#' RD Heterogeneous Treatment Effects
#'
#' 
#' @param data .
#' @param outcome .
#' @param running .
#' @param hte .
#' @param covs .
#' @param cluster .
#' @param cutoff .
#' @param p .
#' @param q .
#' @param bwselect .
#' @param bwJoint .
#' @param kernel .
#' @param vce .
#' @param level .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$est} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$test} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$est$asDF}
#'
#' \code{as.data.frame(results$est)}
#'
#' @export
rdhte <- function(
    data,
    outcome,
    running,
    hte,
    covs,
    cluster,
    cutoff = 0,
    p = 1,
    q = 0,
    bwselect = "mserd",
    bwJoint = FALSE,
    kernel = "triangular",
    vce = "hc3",
    level = 95,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rdhte requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(running)) running <- jmvcore::resolveQuo(jmvcore::enquo(running))
    if ( ! missing(hte)) hte <- jmvcore::resolveQuo(jmvcore::enquo(hte))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(running), running, NULL),
            `if`( ! missing(hte), hte, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(cluster), cluster, NULL))


    options <- rdhteOptions$new(
        outcome = outcome,
        running = running,
        hte = hte,
        covs = covs,
        cluster = cluster,
        cutoff = cutoff,
        p = p,
        q = q,
        bwselect = bwselect,
        bwJoint = bwJoint,
        kernel = kernel,
        vce = vce,
        level = level,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- rdhteClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

